public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }
        while (sc.hasNextInt()) {
            int target = sc.nextInt();
            System.out.println(target + " -> " + firstIndex(a, target));
        }
    }

    public static int firstIndex(int[] a, int target) {
        return firstIndex(a, target, 0, a.length - 1);
    }

    private static int firstIndex(int[] a, int target, int lo, int hi) {
        if (lo > hi) {
            return -1;
        }
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) {
            return firstIndex(a, target, mid + 1, hi);
        }
        if (a[mid] > target) {
            return firstIndex(a, target, lo, mid - 1);
        }
        int earlier = firstIndex(a, target, lo, mid - 1);
        return earlier == -1 ? mid : earlier;
    }
}
